/// `ProposalAction` in this codec family.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ProposalAction {
    /// `batch` carrying `ProposedBatch`.
    Batch(ProposedBatch),
    /// `effect` carrying `ProposedEffect`.
    Effect(ProposedEffect),
    /// `procedure_effect` carrying `ProposedProcedureEffect`.
    ProcedureEffect(ProposedProcedureEffect),
    /// `amend` carrying `Box<ProposedAmendment>`.
    Amend(Box<ProposedAmendment>),
    /// `widen` carrying `ProposedWidening`.
    Widen(ProposedWidening),
    /// `release` carrying `Task`.
    Release(Task),
}

impl ProposalAction {
    /// Checks the payload against the given limits.
    pub fn new(limits: &Limits, value: Self) -> Result<Self, Problem> {
        value.check(limits)?;
        Ok(value)
    }

    fn check(&self, limits: &Limits) -> Result<(), Problem> {
        match self {
            Self::Batch(record) => ProposedBatch::check(record, limits),
            Self::Effect(record) => ProposedEffect::check(record, limits),
            Self::ProcedureEffect(record) => ProposedProcedureEffect::check(record, limits),
            Self::Amend(record) => ProposedAmendment::check(record, limits),
            Self::Widen(record) => ProposedWidening::check(record, limits),
            Self::Release(_) => Ok(()),
        }?;
        Ok(())
    }
}

