/// `Line` in this codec family.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Line {
    /// `words` carrying `ActivityWords`.
    Words(ActivityWords),
    /// `heard` carrying `HeardMessage`.
    Heard(HeardMessage),
    /// `notified` carrying `NotifiedMessage`.
    Notified(NotifiedMessage),
    /// `run_began` carrying `BeganLine`.
    RunBegan(BeganLine),
    /// `run_ended` carrying `EndedLine`.
    RunEnded(EndedLine),
    /// `turn` carrying `TurnLine`.
    Turn(TurnLine),
    /// `decided` carrying `DecidedLine`.
    Decided(DecidedLine),
    /// `milestone` carrying `MilestoneLine`.
    Milestone(MilestoneLine),
    /// `kept` carrying `KeptLine`.
    Kept(KeptLine),
}

impl Line {
    /// Checks the payload against the given limits.
    pub fn new(limits: &Limits, value: Self) -> Result<Self, Problem> {
        value.check(limits)?;
        Ok(value)
    }

    fn check(&self, limits: &Limits) -> Result<(), Problem> {
        match self {
            Self::Words(record) => ActivityWords::check(record, limits),
            Self::Heard(record) => HeardMessage::check(record, limits),
            Self::Notified(record) => NotifiedMessage::check(record, limits),
            Self::Kept(record) => KeptLine::check(record, limits),
            Self::RunBegan(_) | Self::RunEnded(_) | Self::Turn(_) | Self::Decided(_) | Self::Milestone(_) => Ok(()),
        }?;
        Ok(())
    }
}

