        biggest = biggest.max(Update::worst_case_bytes_within(limits)?).max(ResultRow::worst_case_bytes_within(limits)?);
        biggest = biggest.max(Edge::worst_case_bytes_within(limits)?).max(Edge::worst_case_bytes_within(limits)?);
